package raft

import "sync"

type Entry struct {
	Term    int
	Command []byte
}

type Role int

const (
	Follower Role = iota
	Candidate
	Leader
)

type Node struct {
	mu          sync.Mutex
	id          int
	role        Role
	currentTerm int     // persisted
	votedFor    int     // persisted, -1 = none
	log         []Entry // persisted; log[0] is a sentinel {Term: 0} so indexes start at 1
	commitIndex int
	persist     func() // must fsync term, vote and log before we reply
	resetTimer  func() // restart the randomised election timeout
}

type RequestVoteArgs struct{ Term, CandidateID, LastLogIndex, LastLogTerm int }
type RequestVoteReply struct {
	Term        int
	VoteGranted bool
}

func (n *Node) lastIndexTerm() (int, int) {
	i := len(n.log) - 1
	return i, n.log[i].Term
}

func (n *Node) stepDownIfStale(term int) {
	if term > n.currentTerm {
		n.currentTerm, n.votedFor, n.role = term, -1, Follower
	}
}

func (n *Node) RequestVote(a RequestVoteArgs) RequestVoteReply {
	n.mu.Lock()
	defer n.mu.Unlock()
	n.stepDownIfStale(a.Term)
	if a.Term < n.currentTerm {
		return RequestVoteReply{Term: n.currentTerm}
	}
	myIdx, myTerm := n.lastIndexTerm()
	// Election restriction: candidate's log must be at least as up to date (last term first, then length).
	upToDate := a.LastLogTerm > myTerm || (a.LastLogTerm == myTerm && a.LastLogIndex >= myIdx)
	if (n.votedFor == -1 || n.votedFor == a.CandidateID) && upToDate {
		n.votedFor = a.CandidateID
		n.persist() // never vote twice in one term, even across a crash
		n.resetTimer()
		return RequestVoteReply{Term: n.currentTerm, VoteGranted: true}
	}
	n.persist()
	return RequestVoteReply{Term: n.currentTerm}
}

type AppendEntriesArgs struct {
	Term, LeaderID, PrevLogIndex, PrevLogTerm, LeaderCommit int
	Entries                                                 []Entry
}
type AppendEntriesReply struct {
	Term    int
	Success bool
}

func (n *Node) AppendEntries(a AppendEntriesArgs) AppendEntriesReply {
	n.mu.Lock()
	defer n.mu.Unlock()
	n.stepDownIfStale(a.Term)
	if a.Term < n.currentTerm {
		return AppendEntriesReply{Term: n.currentTerm} // stale leader: it will step down
	}
	n.role = Follower // a candidate that hears from the current-term leader steps back
	n.resetTimer()

	// Consistency check: we must hold the entry the leader's new entries follow.
	if a.PrevLogIndex >= len(n.log) || n.log[a.PrevLogIndex].Term != a.PrevLogTerm {
		return AppendEntriesReply{Term: n.currentTerm}
	}
	// Append, truncating only on a real conflict so a delayed, older RPC cannot erase newer entries.
	for i, e := range a.Entries {
		idx := a.PrevLogIndex + 1 + i
		if idx < len(n.log) {
			if n.log[idx].Term == e.Term {
				continue
			}
			n.log = n.log[:idx]
		}
		n.log = append(n.log, a.Entries[i:]...)
		break
	}
	n.persist()
	if a.LeaderCommit > n.commitIndex {
		n.commitIndex = min(a.LeaderCommit, a.PrevLogIndex+len(a.Entries))
	}
	return AppendEntriesReply{Term: n.currentTerm, Success: true}
}

// Leader side: an index is committed when a majority stores it AND it is from the current term.
func (n *Node) advanceCommit(matchIndex []int) {
	for idx := len(n.log) - 1; idx > n.commitIndex; idx-- {
		if n.log[idx].Term != n.currentTerm {
			break // Figure 8: never commit an older-term entry by counting replicas
		}
		count := 1 // the leader itself
		for peer, m := range matchIndex {
			if peer != n.id && m >= idx {
				count++
			}
		}
		if count > len(matchIndex)/2 {
			n.commitIndex = idx
			return
		}
	}
}

# Minimal orchestrated saga. A workflow engine (Temporal, Step Functions) would persist `state` after every
# step so the saga resumes after a crash; here a repository stands in for that.
from dataclasses import dataclass, field
from typing import Callable


class StepFailed(Exception):
    pass


@dataclass
class Step:
    name: str
    action: Callable[[dict], None]       # must be idempotent (keyed by saga id + step name)
    compensate: Callable[[dict], None] | None = None  # None for retriable steps after the pivot
    pivot: bool = False


@dataclass
class SagaState:
    saga_id: str
    ctx: dict
    completed: list[str] = field(default_factory=list)
    status: str = "RUNNING"  # RUNNING | COMPLETED | COMPENSATING | COMPENSATED | NEEDS_HUMAN


class Orchestrator:
    def __init__(self, steps: list[Step], repo):
        self.steps, self.repo = steps, repo

    def run(self, state: SagaState) -> SagaState:
        past_pivot = any(s.pivot and s.name in state.completed for s in self.steps)
        for step in self.steps:
            if step.name in state.completed:
                continue  # resumed after a crash
            try:
                step.action(state.ctx | {"idempotency_key": f"{state.saga_id}:{step.name}"})
            except StepFailed:
                if past_pivot:
                    raise  # after the pivot we only retry forward; the caller schedules a retry
                return self._compensate(state)
            state.completed.append(step.name)
            past_pivot = past_pivot or step.pivot
            self.repo.save(state)
        state.status = "COMPLETED"
        self.repo.save(state)
        return state

    def _compensate(self, state: SagaState) -> SagaState:
        state.status = "COMPENSATING"
        self.repo.save(state)
        by_name = {s.name: s for s in self.steps}
        for name in reversed(state.completed):
            step = by_name[name]
            if step.compensate is None:
                continue
            try:
                step.compensate(state.ctx | {"idempotency_key": f"{state.saga_id}:{name}:undo"})
            except Exception:
                state.status = "NEEDS_HUMAN"  # compensations are retried; persistent failure is escalated
                self.repo.save(state)
                return state
        state.status = "COMPENSATED"
        self.repo.save(state)
        return state


