import { randomUUID } from "node:crypto";

interface Tx { query<T = unknown>(sql: string, params?: unknown[]): Promise<{ rows: T[] }> }
interface Db { transaction<T>(fn: (tx: Tx) => Promise<T>): Promise<T> }
interface Broker { publish(topic: string, key: string, value: string, headers: Record<string, string>): Promise<void> }

// 1. Business change and event commit together, or not at all.
export async function placeOrder(db: Db, customerId: string, items: { sku: string; qty: number }[]) {
  return db.transaction(async (tx) => {
    const orderId = randomUUID();
    await tx.query("INSERT INTO orders (id, customer_id, status) VALUES ($1, $2, 'PENDING')", [orderId, customerId]);
    await tx.query(
      "INSERT INTO outbox (id, aggregate_type, aggregate_id, type, payload) VALUES ($1, 'order', $2, 'order.created.v1', $3)",
      [randomUUID(), orderId, JSON.stringify({ orderId, customerId, items })],
    );
    return orderId;
  });
}

// 2. Relay: several workers can run; SKIP LOCKED stops them claiming the same rows.
// Ordering holds per aggregate because the broker partitions by key; a single worker per key range keeps it strict.
export async function relayOnce(db: Db, broker: Broker, batch = 100): Promise<number> {
  return db.transaction(async (tx) => {
    const { rows } = await tx.query<{ id: string; aggregate_type: string; aggregate_id: string; type: string; payload: string }>(
      `SELECT id, aggregate_type, aggregate_id, type, payload FROM outbox
        WHERE published_at IS NULL ORDER BY created_at LIMIT $1 FOR UPDATE SKIP LOCKED`,
      [batch],
    );
    for (const r of rows) {
      // A crash after publish but before commit republishes on restart: at-least-once.
      await broker.publish(`${r.aggregate_type}-events`, r.aggregate_id, r.payload, { "message-id": r.id, type: r.type });
    }
    if (rows.length > 0) {
      await tx.query("UPDATE outbox SET published_at = now() WHERE id = ANY($1)", [rows.map((r) => r.id)]);
    }
    return rows.length;
  });
}

// 3. Consumer: the dedup insert and the side effect share one transaction, so a duplicate is a no-op.
export async function onOrderCreated(db: Db, messageId: string, payload: { orderId: string; items: { sku: string; qty: number }[] }) {
  await db.transaction(async (tx) => {
    const { rows } = await tx.query(
      "INSERT INTO processed_messages (consumer, message_id) VALUES ('inventory', $1) ON CONFLICT DO NOTHING RETURNING message_id",
      [messageId],
    );
    if (rows.length === 0) return; // already handled
    for (const { sku, qty } of payload.items) {
      await tx.query("INSERT INTO reservations (order_id, sku, qty) VALUES ($1, $2, $3)", [payload.orderId, sku, qty]);
    }
  });
}

