"""Dynamo-style quorum simulation: N replicas, writes wait for W acks, reads ask R replicas.

R + W > N  -> every read set overlaps every write set, so the newest acknowledged version is seen.
R + W <= N -> a read can land entirely on replicas that missed the write.
(Overlap alone is not linearizability: concurrent writes, partial failures and sloppy quorums still bite.)
"""
import random
from dataclasses import dataclass


@dataclass
class Versioned:
    version: int
    value: str


class Cluster:
    def __init__(self, n: int, w: int, r: int, seed: int = 7):
        self.n, self.w, self.r = n, w, r
        self.replicas: list[Versioned] = [Versioned(0, "init") for _ in range(n)]
        self.version = 0
        self.rng = random.Random(seed)

    def write(self, value: str, reachable: set[int] | None = None) -> bool:
        reachable = reachable if reachable is not None else set(range(self.n))
        if len(reachable) < self.w:
            return False  # cannot reach a write quorum: refuse (consistency over availability)
        self.version += 1
        # Only W replicas get it before we ack; the rest lag (async repair would catch them up later).
        for i in self.rng.sample(sorted(reachable), self.w):
            self.replicas[i] = Versioned(self.version, value)
        return True

    def read(self) -> Versioned:
        asked = self.rng.sample(range(self.n), self.r)
        newest = max((self.replicas[i] for i in asked), key=lambda v: v.version)
        # Read repair: push the newest version to the stale replicas we touched.
        for i in asked:
            if self.replicas[i].version < newest.version:
                self.replicas[i] = newest
        return newest


def stale_read_rate(n: int, w: int, r: int, trials: int = 10_000) -> float:
    stale = 0
    for t in range(trials):
        c = Cluster(n, w, r, seed=t)
        c.write("v1")
        stale += c.read().version != 1
    return stale / trials


if __name__ == "__main__":
    for n, w, r in [(3, 2, 2), (3, 1, 1), (5, 3, 3), (5, 2, 2), (3, 3, 1)]:
        tag = "overlap" if r + w > n else "no overlap"
        print(f"N={n} W={w} R={r} ({tag}): stale reads {stale_read_rate(n, w, r):.1%}")
    # N=3 W=1 R=1 is stale about 2 times in 3; N=5 W=2 R=2 about 3 times in 10; overlapping settings never.
